const STOPWORDS = new Set(['and', 'the', 'is', 'in', 'to', 'through', 'using', 'of', 'for', 'a']);
const tokenizedDocs = inputs.documents.map((doc, docId) => {
  const words = doc
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, '')
    .split(/\s+/)
    .filter((w) => w.length > 2 && !STOPWORDS.has(w));
  return { docId, words };
});
return { tokenizedDocs };
```

--- Cell ID: 8becdfd3-41bd-4ef6-977d-40e71209088e ---
```javascript
const docCount = inputs.tokenizedDocs.length;
const docFreq = {};
const termFreqs = [];

for (const d of inputs.tokenizedDocs) {
  const tf = {};
  const seenInDoc = new Set();
  for (const w of d.words) {
    tf[w] = (tf[w] || 0) + 1;
    seenInDoc.add(w);
  }
  termFreqs.push({ docId: d.docId, tf, wordCount: d.words.length });
  for (const w of seenInDoc) {
    docFreq[w] = (docFreq[w] || 0) + 1;
  }
}

return { docCount, docFreq, termFreqs };
```

--- Cell ID: 6dd8e881-083c-4bd6-84f9-8f42115a3df3 ---
```javascript
const { docCount, docFreq, termFreqs } = inputs;
const idfMap = {};
for (const [w, df] of Object.entries(docFreq)) {
  const idf = Math.log((docCount - 1) / (df + 1)) + 1;
  idfMap[w] = Math.round(idf * 1000) / 1000;
}
return { idfMap, termFreqs };
```

--- Cell ID: 1b37207d-a8b7-4fde-b5c9-d20e7cdddbd0 ---
```javascript
const { idfMap, termFreqs } = inputs;
const docVectors = termFreqs.map((d) => {
  const vector = {};
  let sumSq = 0;
  for (const [w, count] of Object.entries(d.tf)) {
    const tf = count / d.wordCount;
    const idf = idfMap[w] || 1;
    const score = tf * idf;
    vector[w] = score;
    sumSq += score * score;
  }
  const magnitude = Math.sqrt(sumSq) || 1;
  const normalized = {};
  for (const [w, sc] of Object.entries(vector)) {
    normalized[w] = Math.round((sc / magnitude) * 1000) / 1000;
  }
  return { docId: d.docId, vector: normalized };
});
return { docVectors };
```

--- Cell ID: 01e78df8-9dad-467f-a710-baecab8ae86f ---
```javascript
const vectors = inputs.docVectors;
const pairwiseScores = [];

for (let i = 0; i < vectors.length; i++) {
  for (let j = i + 1; j < vectors.length; j++) {
    const v1 = vectors[i].vector;
    const v2 = vectors[j].vector;
    let dot = 0;
    for (const [k, val] of Object.entries(v1)) {
      if (v2[k]) {
        dot += val * v2[k];
      }
    }
    pairwiseScores.push(Math.round(dot * 1000) / 1000);
  }
}
return { pairwiseScores };
```

--- Cell ID: 03e5fe4d-2846-4389-93a9-99774018faa0 ---
```javascript
const scores = inputs.pairwiseScores;
let sum = 0;
let maxSim = -1;
let minSim = 2;
let strongPairs = 0;

for (const s of scores) {
  sum += s;
  if (s > maxSim) maxSim = s;
  if (s < minSim) minSim = s;
  if (s >= 0.20) strongPairs++;
}

const avgSim = Math.round((sum / (scores.length || 1)) * 1000) / 1000;

return {
  totalComparisons: scores.length,
  averageSimilarity: avgSim,
  maxSimilarity: maxSim,
  minSimilarity: minSim,
  strongConnectionCount: strongPairs,
  corpusCohesive: avgSim > 0.05 && strongPairs >= 3,
};
```

Locate the bug causing the final output discrepancy, fix it using notebook_edit_cell, and finish.

